import React from 'react';
import { PieChart, pieArcLabelClasses } from '@mui/x-charts/PieChart';

const PieChartComponent = ({ data, width, height }) => {
    const colors = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#FF00FF'];
    return (

        <PieChart
            series={[{
                data,
                arcLabel: (item) => `${item.value}%`, arcLabelMinAngle: 10, color: 'white !important',
                arcLabelRadius: '60%',
                arcLabelStyle: { fontWeight: 'normal', color: 'white', fontSize: '6px' },
                color: colors,
            }]} // Passing the data as a prop to the series
            sx={{
                [`& .${pieArcLabelClasses.root}`]: {
                    fontSize: '12px',

                },
            }}
            width={width}
            height={height}

        />
    );
};

export default PieChartComponent;
