import React, { useCallback, useState } from 'react';
import './coin_toss.css';
import { Button, Grid, Stack, TextField, Typography } from '@mui/material';
import { PieChart } from '@mui/x-charts';
import PieChartComponent from 'src/components/chart/PieChart';
import BarChartComponent from 'src/components/chart/CoinBarChart';
import LineChartComponent from 'src/components/chart/CoinLineChart';
import { printArray } from 'src/utils/printArray';
const valueFormatterXPieChart = (value) => `${value?.toLocaleString()} %`;

const CoinFlip = () => {
    const [coins, setCoins] = useState([{ id: 0, result: '', isFlipping: false }]); // Danh sách các đồng xu
    const [headsCount, setHeadsCount] = useState(0); // Số lần xuất hiện heads
    const [tailsCount, setTailsCount] = useState(0); // Số lần xuất hiện tails
    const [flipCount, setFlipCount] = useState(0); // Tổng số lần tung đồng xu
    const [flipInput, setFlipInput] = useState(1);
    const [headsHistory, setHeadHistory] = useState([0]); // Số lần xuất hiện heads
    const [tailsHistory, setTailsHistory] = useState([0]); // Số lần xuất hiện tails
    const [totalHistory, setTotalHistory] = useState([]); // Số lần xuất hiện tails
    const [isRolling, setIsRolling] = useState(false);
    const handleAddToHistory = (value) => {
        setTotalHistory(prevHistory => [...prevHistory, value]);
    };
    // Thêm một đồng xu mới
    const addCoin = () => {
        setCoins([...coins, { id: coins.length, result: '', isFlipping: false }]);
        setHeadsCount(0);
        setTailsCount(0);
        setFlipCount(0);
    };
    // Xử lý thay đổi số lần tung từ input
    const handleInputChange = (e) => {
        const value = parseInt(e.target.value) || 1;
        setFlipInput(Math.max(1, value)); // Không cho phép nhập số lần < 1
    };
    // Tung tất cả đồng xu
    const handleFlipAll = () => {
        const updatedCoins = coins.map(coin => ({ ...coin, result: '', isFlipping: true }));
        const newHeadsHistory = [...headsHistory];
        const newTailsHistory = [...tailsHistory];
        setCoins(updatedCoins);
        let flag = false;
        setTimeout(() => {
            let newHeadsCount = 0;
            let newTailsCount = 0;

            const updatedCoinsWithResults = coins.map(coin => {
                const result = Math.random() <= 0.5 ? 'heads' : 'tails';
                if (result === 'heads') {
                    newHeadsCount++;
                    newHeadsHistory.push(newHeadsHistory[newHeadsHistory.length - 1] + 1);
                    newTailsHistory.push(newTailsHistory[newTailsHistory.length - 1]);
                    handleAddToHistory(1)
                } else {
                    newTailsCount++;
                    newTailsHistory.push(newTailsHistory[newTailsHistory.length - 1] + 1);
                    newHeadsHistory.push(newHeadsHistory[newHeadsHistory.length - 1]);
                    handleAddToHistory(0)
                }
                return { ...coin, result, isFlipping: false };
            });

            setCoins(updatedCoinsWithResults);
            setHeadsCount(prev => prev + newHeadsCount);
            setTailsCount(prev => prev + newTailsCount);
            setFlipCount(prev => prev + 1);
            setHeadHistory(newHeadsHistory);
            setTailsHistory(newTailsHistory);
        }, 100); // Thời gian chờ để hoàn tất animation

    };
    // Làm mới toàn bộ trạng thái
    const handleReset = () => {
        setCoins([{ id: 0, result: '', isFlipping: false }]);
        setHeadsCount(0);
        setTailsCount(0);
        setFlipCount(0);
        setTotalHistory([])

    };
    const handleFlipInput = () => {
        const newHeadsHistory = [0];
        const newTailsHistory = [0];
        const updatedCoins = coins.map(coin => ({ ...coin, result: '', isFlipping: true }));
        setTotalHistory([])
        setCoins(updatedCoins);
        let newHeadsCount = 0;
        let newTailsCount = 0;
        for (let index = 0; index < flipInput; index++) {
            setTimeout(() => {
                const updatedCoinsWithResults = coins.map((coin) => {
                    const result = Math.random() <= 0.5 ? 'heads' : 'tails';
                    if (result === 'heads') {
                        newHeadsCount++;
                        newHeadsHistory.push(newHeadsHistory[newHeadsHistory.length - 1] + 1);
                        newTailsHistory.push(newTailsHistory[newTailsHistory.length - 1]);
                        handleAddToHistory(1)
                    } else {
                        newTailsCount++;
                        newTailsHistory.push(newTailsHistory[newTailsHistory.length - 1] + 1);
                        newHeadsHistory.push(newHeadsHistory[newHeadsHistory.length - 1]);
                        handleAddToHistory(0)
                    }
                    return { ...coin, result, isFlipping: false };
                });
                setCoins(updatedCoinsWithResults);
                setHeadsCount(newHeadsCount);
                setTailsCount(newTailsCount);
                setFlipCount(flipInput);
                setHeadHistory(newHeadsHistory);
                setTailsHistory(newTailsHistory);
            }, 300); // Thời gian chờ để hoàn tất animation
        }
    };


    const removeLastCoin = () => {
        if (coins.length > 1) {
            setCoins(coins.slice(0, -1));
            setHeadsCount(0);
            setTailsCount(0);
            setFlipCount(0);
        } else {
            handleReset(); // Nếu chỉ còn 1 đồng xu, reset trạng thái
        }
    };
    // Calculate the percentages
    const totalFlips = headsCount + tailsCount;
    const headsPercentage = totalFlips ? ((headsCount / totalFlips) * 100).toFixed(2) : 0;
    const tailsPercentage = totalFlips ? ((tailsCount / totalFlips) * 100).toFixed(2) : 0;

    const dataPieChart = [
        { id: 0, value: headsPercentage, label: 'Mặt Ngửa' },
        { id: 1, value: tailsPercentage, label: 'Mặt Sấp' },
    ];
    const calculateMedian = (arr) => {
        if (arr.length === 0) return 0;
        const sortedArr = [...arr].sort((a, b) => a - b); // Sort the array
        const middle = Math.floor(sortedArr.length / 2);
        if (sortedArr.length % 2 === 0) {
            // If even number of elements, return the average of the two middle elements
            return (sortedArr[middle - 1] + sortedArr[middle]) / 2;
        } else {
            // If odd, return the middle element
            return sortedArr[middle];
        }
    };

    const dataBarChart = [headsCount, tailsCount]
    // Số trung bình
    const mean = ((headsCount * 1) + (tailsCount * 0)) / flipCount || 0;
    const median = calculateMedian(totalHistory);
    // const calculateQuartiles = (arr) => {
    //     if (arr.length === 0) return { Q1: 0, Q2: 0, Q3: 0 };

    //     const sortedArr = [...arr].sort((a, b) => a - b); // Sắp xếp dữ liệu tăng dần
    //     const median = calculateMedian(sortedArr); // Tính Q2

    //     // Chia mảng thành hai phần
    //     const lowerHalf = sortedArr.filter(num => num < median); // Dữ liệu bên trái Q2
    //     const upperHalf = sortedArr.filter(num => num > median); // Dữ liệu bên phải Q2

    //     // Tính Q1 và Q3
    //     const Q1 = calculateMedian(lowerHalf);
    //     const Q3 = calculateMedian(upperHalf);

    //     return { Q1, Q2: median, Q3 };
    // };


    //const { Q1, Q2, Q3 } = calculateQuartiles(totalHistory);


    return (
        <>
            <Grid container spacing={2} sx={{ pl: 5 }}>
                <Grid item xs={12}>
                    <Typography
                        fontWeight="bold"
                        variant="h3"
                        sx={{ mb: 2, textAlign: 'center' }}
                    >
                        Minh họa bài toán đồng xu
                    </Typography>
                    <div className="coin-container">
                        {coins.map((coin) => (
                            <div
                                key={coin.id}
                                id="coin"
                                className={coin.result} // Thêm class tương ứng với kết quả heads/tails
                            >
                                <div className="side-a">
                                    <img src="/coin_02.png" alt="Coin Tails" width="100px" />
                                </div>
                                <div className="side-b">
                                    <img src="/coin_01.png" alt="Coin Heads" width="100px" />
                                </div>
                            </div>
                        ))}
                    </div>
                    {/* Nút thêm đồng xu */}
                    <Button variant="contained" onClick={addCoin} color="secondary" disabled={isRolling}>
                        Thêm đồng xu
                    </Button>
                    <Button style={{ marginLeft: '6px' }} onClick={removeLastCoin} variant="contained" color="error" disabled={isRolling}>
                        Xóa đồng xu
                    </Button>
                    <Button style={{ marginLeft: '6px' }} onClick={handleFlipAll} variant="contained" color="primary" disabled={isRolling}>
                        Tung đồng xu
                    </Button>
                    <Button style={{ marginLeft: '6px' }} onClick={handleReset} variant="contained" color="info" disabled={isRolling}>
                        Làm mới
                    </Button>
                    {/* Input nhập số lần tung */}
                    <Stack direction="row" spacing={2} alignItems="center" marginTop={2} marginBottom={2}>
                        <label htmlFor="flip-count-input">Nhập số lần tung đồng xu:</label>
                        <TextField
                            id="flip-count-input"
                            type="number"
                            value={flipInput}
                            onChange={handleInputChange}
                            variant="outlined"
                            size="small"
                            inputProps={{ min: 1 }}
                            sx={{ width: '120px' }}
                        />
                        <Button onClick={handleFlipInput} variant="contained" color="success" disabled={isRolling}>
                            Xác nhận
                        </Button>
                    </Stack>
                    {/* Hiển thị số liệu */}
                    <div style={{ marginTop: '16px' }}>
                        <h3>Số lần tung: {flipCount}</h3>
                        <h3>Số lần xuất hiện mặt ngửa (1): {headsCount} <span>({headsPercentage + '%'})</span> </h3>
                        <h3>Số lần xuất hiện mặt sấp (0): {tailsCount}   <span>({tailsPercentage + '%'})</span> </h3>
                        <h3>  Kết quả:

                        </h3>
                        <h3>
                            {'['}
                            {totalHistory.map((item, index) => (
                                <>
                                    {item}
                                    {/* Kiểm tra nếu không phải phần tử cuối cùng thì thêm dấu ',' */}
                                    {(index + 1) !== totalHistory.length && ','}
                                    {/* Thêm thẻ <br /> sau mỗi 20 phần tử */}
                                    {(index + 1) % 80 === 0 && <br />}
                                </>
                            ))}
                            {']'}
                        </h3>
                        <h3>Số trung bình: {mean.toFixed(2)}</h3>
                        <h3>Trung vị: {median} </h3>
                        {/* <h3>Tứ phân vị: </h3>
                        <div style={{ marginLeft: '6px' }}>
                            <ul style={{ marginLeft: '24px' }} >
                                <li>Q1: {Q1}</li>
                                <li>Q2: {Q2}</li>
                                <li>Q3: {Q3}</li>
                            </ul>
                        </div> */}
                        <h3>Mốt:{' '}
                            {headsCount > tailsCount ? 'Mặt ngửa' :
                                tailsCount > headsCount ? 'Mặt sấp' :
                                    'Không có mốt'}
                        </h3>
                    </div>
                    <Grid container spacing={2} sx={{ mt: 2 }}>
                        <Grid item xs={12} sm={12} md={6}>
                            <Typography variant='h6' sx={{ mb: 5 }}>Biểu đồ quạt</Typography>
                            <PieChartComponent data={dataPieChart} width={400} height={200} />
                        </Grid>
                        <Grid item xs={12} sm={12} md={6}>
                            <Typography variant='h6'>Biểu đồ cột</Typography>
                            <BarChartComponent dataBarChart={dataBarChart} />
                        </Grid>
                        <Grid item xs={12} sm={12} md={12}>
                            <Typography variant='h6' sx={{ mb: 3 }}>Biểu đồ đoạn thẳng</Typography>
                            <LineChartComponent headsHistory={headsHistory} tailsHistory={tailsHistory} flipCount={flipCount} coins={coins} />
                        </Grid>
                    </Grid>
                </Grid>
            </Grid >

        </>
    );
};

export default CoinFlip;
