import * as React from 'react';
import { LineChart } from '@mui/x-charts/LineChart';

export default function CoinLineChartComponent({ tailsHistory, headsHistory, flipCount, coins }) {
    // Create x-axis data of length 10, starting from 0 and ending at headsHistory.length
    const generateRandomXAxis = (count, flipCount) => {
        // Calculate the step size for even spacing
        const step = Math.floor(flipCount / (count - 1)); // -1 to leave space for the last value (flipCount)

        // Create an array of evenly spaced values
        const result = Array.from({ length: count - 1 }, (_, i) => i * step);

        // Ensure the last value is exactly flipCount
        result.push(flipCount);

        return result;
    };

    // Usage
    const xAxis = generateRandomXAxis(flipCount < 10 ? (flipCount + 1) : 10, flipCount);

    // Generate new heads and tails data for the chart based on xAxis indices
    const headsData = xAxis.map(index => (headsHistory[index * coins.length]) || 0); // Ensure safe access to history
    const tailsData = xAxis.map(index => (tailsHistory[index * coins.length]) || 0); // Ensure safe access to history


    return (
        <LineChart
            xAxis={[{ data: xAxis }]}  // Use the new xAxis array
            series={[
                {
                    data: headsData, // Data for the first line (heads)
                    label: 'Mặt ngửa', // Label for the first line
                },
                {
                    data: tailsData, // Data for the second line (tails)
                    label: 'Mặt sấp', // Label for the second line
                },
            ]}
            width={500}
            height={300}
        />
    );
}
