import * as React from 'react';
import { BarChart } from '@mui/x-charts/BarChart';

export default function CoinBarChartComponent({ dataBarChart }) {
    return (
        <BarChart
            xAxis={[{
                scaleType: 'band', data: ['Mặt Ngửa', 'Mặt Sấp'], colorMap: {
                    type: "ordinal",
                    colors: ['#02b2af', '#2e96ff'],
                },
            }]}
            series={[
                {
                    data: dataBarChart, // Values for heads and tails

                },

            ]}
            width={500}
            height={300}
        />
    );
}